#include <algorithm>
#include <cstdint>
#include <string>
#include <utility>
#include <vector>

std::vector<std::pair<std::size_t, std::string>> findStrings(const std::vector<std::uint8_t>& bytes, std::size_t minLength)
{
    auto printable = [](std::uint8_t b) { return b >= 0x20 && b <= 0x7E; };
    std::vector<std::pair<std::size_t, std::string>> found;

    // ASCII: runs of printable bytes.
    std::string run;
    std::size_t start{ 0 };
    for (std::size_t i{ 0 }; i <= bytes.size(); ++i)
    {
        if (i < bytes.size() && printable(bytes[i]))
        {
            if (run.empty()) start = i;
            run += static_cast<char>(bytes[i]);
            continue;
        }
        if (run.size() >= minLength) found.push_back({ start, run });
        run.clear();
    }

    // UTF-16: runs of (printable, 0) pairs at even offsets.
    run.clear();
    for (std::size_t i{ 0 }; ; i += 2)
    {
        const bool unit{ i + 1 < bytes.size() && printable(bytes[i]) && bytes[i + 1] == 0 };
        if (unit)
        {
            if (run.empty()) start = i;
            run += static_cast<char>(bytes[i]);
            continue;
        }
        if (run.size() >= minLength) found.push_back({ start, run });
        run.clear();
        if (i + 1 >= bytes.size()) break;
    }

    std::sort(found.begin(), found.end());
    return found;
}

