using S = std::vector<std::pair<std::size_t, std::string>>;
static std::vector<std::uint8_t> bytesOf(std::initializer_list<int> v) { std::vector<std::uint8_t> b; for (int x : v) b.push_back(static_cast<std::uint8_t>(x)); return b; }
TEST("the example")
{
    const auto b{ bytesOf({ 0, 'H', 'P', ':', ' ', '9', '9', 1, 'S', 0, 'a', 0, 'v', 0, 'e', 0, 0, 0 }) };
    CHECK(findStrings(b, 4) == S({ { 1, "HP: 99" }, { 8, "Save" } }));
}
TEST("too short") { CHECK(findStrings(bytesOf({ 'a', 'b', 'c', 0 }), 4).empty()); }
TEST("a string at the very end") { CHECK(findStrings(bytesOf({ 0, 0, 'q', 'u', 'e', 's', 't' }), 4) == S({ { 2, "quest" } })); }
TEST("UTF-16 must start at an even offset") { CHECK(findStrings(bytesOf({ 0, 'A', 0, 'B', 0, 'C', 0, 'D', 0 }), 4).empty()); }
TEST("UTF-16 at the end of the block") { CHECK(findStrings(bytesOf({ 'G', 0, 'o', 0, 'l', 0, 'd', 0 }), 4) == S({ { 0, "Gold" } })); }
TEST("non-printable bytes split runs") { CHECK(findStrings(bytesOf({ 'a', 'b', 'c', 'd', 0x07, 'e', 'f', 'g', 'h', 'i' }), 4) == S({ { 0, "abcd" }, { 5, "efghi" } })); }
TEST("nothing at all") { CHECK(findStrings({}, 4).empty()); }

